message.content:
{
  "title": "The Glass Diver's Escape",
  "gate_token": "GSM_TXx5Uu72mkU_58ImXg",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "The team gathers at the ruined city's edge.",
      "visual_description": "Crumbled walls and torn royal banners flutter in the wind as Mara the Cartographer unfolds a map under a gray sky.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox"]
    },
    {
      "scene_number": 2,
      "caption": "The Oracle Lamp warns of a cursed tower.",
      "visual_description": "Inside a collapsed archway, the Oracle Lamp flickers, its flame-eye casting shadows on cracked stone.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 3,
      "caption": "The Glass Diver scouts through a shattered window.",
      "visual_description": "Glass Diver presses his helmet against a broken pane, peering into a dark chamber lined with old weapons.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 4,
      "caption": "Mara traces a path past the castle gates.",
      "visual_description": "Mara kneels, inking a route on her map while the iron gates loom behind her, rusted and partially open.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 5,
      "caption": "The Tin Fox discovers a hidden key.",
      "visual_description": "Tin Fox's key-wind tail spins as it nudges a brass key from under a pile of fallen rubble.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "The Sleeping Tax Collector blocks a narrow corridor.",
      "visual_description": "A dozing figure slumped against a stack of ledgers, papers stuck to sleeves, snoring softly in a cramped passage.",
      "characters": ["sleeping_tax_collector"]
    },
    {
      "scene_number": 7,
      "caption": "The Glass Diver swims through a mirror into a locked room.",
      "visual_description": "Glass Diver's reflection ripples as he steps through a tall mirror, emerging into a dusty study filled with old maps.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "Mara consults the Oracle Lamp about a magic door.",
      "visual_description": "The Oracle Lamp glows brighter, casting rune-shaped shadows on a stone door etched with symbols.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 9,
      "caption": "The Tin Fox leads the way around an armored patrol.",
      "visual_description": "Tin Fox's blue glass eyes gleam as it crouches behind a broken wall, pointing with its metal tail toward a side route.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 10,
      "caption": "The Sleeping Tax Collector stirs but does not awake.",
      "visual_description": "The tax collector shifts, a stamped paper falling from his sleeve as the team tiptoes past his pile of ledgers.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "The Glass Diver retrieves a crucial item from a window.",
      "visual_description": "Glass Diver reaches through a high, arched window, pulling a rolled scroll from a sill above a dried fountain.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 12,
      "caption": "Mara deciphers a map near the royal banner.",
      "visual_description": "Mara holds the scroll against a torn banner, her compass glinting as she aligns symbols with the old flag's pattern.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "The Oracle Lamp reveals a trap in the tower staircase.",
      "visual_description": "The lamp's flame flickers red, casting a warning glow on a spiral stair where the steps seem to shift.",
      "characters": ["oracle_lamp", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The Tin Fox triggers a false floor safely.",
      "visual_description": "Tin Fox scampers across the steps, its light weight causing a single stone to drop, revealing a pit below.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 15,
      "caption": "The Glass Diver dives through a second mirror into the tower's heart.",
      "visual_description": "Inside the tower, a cracked mirror reflects the team as Glass Diver steps through, landing in a chamber with a glowing orb.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "Mara finds the exit route to the bridge.",
      "visual_description": "Mara traces a final line on her map, pointing toward a distant bridge that arcs over a dry moat.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The team races across the bridge under falling rubble.",
      "visual_description": "Stones tumble from the tower as the team sprints across the stone bridge, banners snapping in the wind.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    },
    {
      "scene_number": 18,
      "caption": "They escape into the mist beyond the city.",
      "visual_description": "The bridge ends in a foggy path; the team pauses, catching breath, as the ruined city fades behind them.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox", "oracle_lamp", "sleeping_tax_collector"]
    }
  ]
}

